      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin, a highly lipophilic conjugated polyene, shows high oral bioavailability when ingested with fat, supporting the possibility of adequate absorption for the lipophilic retinoid-like fenretinide.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Fenretinide is predicted to have absolute oral bioavailability at or above 20% based on transferable high-bioavailability evidence from structurally related lipophilic anilides and a conjugated polyene, despite the absence of direct fenretinide absolute F data.",
